<https://example.org/openevidence/questions/q_addison_disease_efficacy> a holon:ClinicalQuestionHolon ;
    oe:questionText "How effective is prednisone compared with other agents for Addison Disease?"^^xsd:string ;
    oe:answerText "Just Anorexia?."^^xsd:string ;
    oe:belongsToSpecialty "Endocrinology" ;
    holon:hasInteriorGraph <https://example.org/openevidence/questions/q_addison_disease_efficacy-int> ;
    holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_addison_disease_efficacy-bou> ;
