    holon:evidenceLevel "Level-4" ;
    holon:assessedBy <https://example.org/openevidence/questions/openevidence_ai> ;
    holon:recordedOn "2026-12-31"^^xsd:date ;
    oe:cites <https://example.org/openevidence/sources/36102024> ;
    holon:inHolon <https://example.org/openevidence/questions/q_addison_disease_efficacy> ;
    oe:effectiveness "inconclusive" .
<https://example.org/openevidence/generated/ev_q_addison_disease_efficacy_0-tt> rdf:subject <https://example.org/openevidence/drugs/prednisone> ;
